class BankAccount {
    private String secretPin;         // NOT accessible in subclass
    protected String accountNumber;   // Accessible in subclass
    public double balance;            // Accessible everywhere

    public BankAccount(String pin, String accNum, double bal) {
        this.secretPin = pin;
        this.accountNumber = accNum;
        this.balance = bal;
    }

    // Public getter gives child safe access to private parent field
    public boolean verifyPin(String attempt) {
        return this.secretPin.equals(attempt);
    }
}

class PremiumAccount extends BankAccount {
    public PremiumAccount(String pin, String accNum, double bal) {
        super(pin, accNum, bal);
    }

    public void printAudit() {
        // Direct access to protected and public members
        System.out.println("Account: " + accountNumber + ", Balance: $" + balance);

        // COMPILER ERROR if uncommented:
        // System.out.println("Pin: " + secretPin);

        // Safe access via public method:
        System.out.println("Pin valid: " + verifyPin("1234"));
    }
}

public class ExtendsDemo {
    public static void main(String[] args) {
        PremiumAccount pa = new PremiumAccount("1234", "PREM-888", 5000.0);
        pa.printAudit();
    }
}

