class Account {
    private String pin;
    protected double balance;

    public Account(String pin, double balance) {
        this.pin = pin;
        this.balance = balance;
    }

    public boolean validatePin(String attempt) {
        return this.pin.equals(attempt);
    }
}

class SavingsAccount extends Account {
    private double interestRate;

    public SavingsAccount(String pin, double balance, double interestRate) {
        super(pin, balance);
        this.interestRate = interestRate;
    }

    public void applyInterest(String pinAttempt) {
        if (validatePin(pinAttempt)) {
            double interest = balance * (interestRate / 100.0);
            balance += interest;
            System.out.println("Interest applied: $" + interest + ". New balance: $" + balance);
        } else {
            System.out.println("Invalid PIN attempt! Interest application rejected.");
        }
    }
}

public class Main {
    public static void main(String[] args) {
        SavingsAccount sa = new SavingsAccount("4321", 1000.0, 5.0);
        sa.applyInterest("4321");
        sa.applyInterest("9999");
    }
}

class Vehicle {
    protected String vin;
    protected double tareWeightKg;

    public Vehicle(String vin, double tareWeightKg) {
        this.vin = vin;
        this.tareWeightKg = tareWeightKg;
    }
}

class Truck extends Vehicle {
    private double maxPayloadKg;
    private double currentCargoKg;

    public Truck(String vin, double tareWeightKg, double maxPayloadKg) {
        super(vin, tareWeightKg);
        this.maxPayloadKg = maxPayloadKg;
        this.currentCargoKg = 0.0;
    }

    public void loadCargo(double weightKg) {
        if (currentCargoKg + weightKg <= maxPayloadKg) {
            currentCargoKg += weightKg;
            System.out.println("Loaded " + weightKg + " kg cargo on " + vin);
        } else {
            double remaining = maxPayloadKg - currentCargoKg;
            System.out.println("Rejected! " + weightKg + " kg exceeds remaining capacity of " + remaining + " kg");
        }
    }
}

public class Main {
    public static void main(String[] args) {
        Truck truck = new Truck("VIN-TRK-01", 5000.0, 5000.0);
        truck.loadCargo(3000.0);
        truck.loadCargo(6000.0);
    }
}

