class BaseKey {
    protected String keyHash;
    public BaseKey(String keyHash) { this.keyHash = keyHash; }
}

class CustomKey extends BaseKey {
    private int version;
    private String algorithm;

    public CustomKey(String keyHash, int version, String algorithm) {
        super(keyHash);
        this.version = version;
        this.algorithm = algorithm;
    }

    public void display() {
        System.out.println("Key " + keyHash + " version: " + version + " (Algorithm: " + algorithm + ")");
    }
}

public class Main {
    public static void main(String[] args) {
        CustomKey k = new CustomKey("0xABC", 2, "SHA-256");
        k.display();
    }
}

class Sensor {
    protected String sensorId;
    protected String location;
    protected double lastReading;

    public Sensor(String sensorId, String location) {
        this.sensorId = sensorId;
        this.location = location;
        this.lastReading = 0.0;
    }
}

class TemperatureSensor extends Sensor {
    private double alertThresholdCelsius;

    public TemperatureSensor(String sensorId, String location, double threshold) {
        super(sensorId, location);
        this.alertThresholdCelsius = threshold;
    }

    public void recordReading(double value) {
        this.lastReading = value;
        if (value > alertThresholdCelsius) {
            System.out.println("ALERT! Sensor " + sensorId + " [" + location + "] reading: " + value + " C exceeds threshold of " + alertThresholdCelsius + " C");
        } else {
            System.out.println("Sensor " + sensorId + " [" + location + "] reading: " + value + " C (Normal)");
        }
    }
}

public class Main {
    public static void main(String[] args) {
        TemperatureSensor ts = new TemperatureSensor("S-101", "Server Room", 30.0);
        ts.recordReading(24.5);
        ts.recordReading(36.2);
    }
}
